head.script:
// 테스트 설명, 유효성 값 설정
//  - "Header Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성)
//    동작 영역인 Header Column 에만 imageStyle / inputType / viewType / imageWidth / imageHeight 를 설정
scwin.tData = {
    "description" : "[column > P > imageStyle]<br/>Header Column 에 표시되는 이미지의 Inline Style 을 설정합니다.",
    "validation" : [
        "Column 의 inputType='textImage', viewType='icon' 인 경우에 동작합니다.",
        "Inline Style 문자열 설정 시, 이미지에 적용할 CSS 속성을 'width:16px;height:16px' 형식의 Inline Style 문자열로 설정합니다.",
        "Header Column 의 이미지에는 별도의 CSS 클래스가 부여되지 않으므로, 아이콘의 크기와 여백, 정렬 등의 스타일을 imageStyle 속성으로 제어합니다.",
        "이미지의 크기를 지정하는 imageWidth, imageHeight 속성은 Header Column 에는 적용되지 않습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_imageStyle.setValue("width:36px;height:36px");
    con_inputType.setValue("textImage");
    con_viewType.setValue("icon");
    con_imageWidthHeight.setValue("");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - 검증 대상 : 첨부파일 Header Column(column2) — imageStyle / inputType / viewType / imageWidth·imageHeight 를 옵션값으로 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
//    imageSrc 는 원본 16 x 16 svg 고정, imageAlign 미설정(이미지는 텍스트 오른쪽)
//  - Body Column 은 모두 일반 text Column
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    let cImageStyle = con_imageStyle.getValue();
    let cInputType = con_inputType.getValue();
    let cViewType = con_viewType.getValue();
    let cImageWidthHeight = con_imageWidthHeight.getValue();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 옵션값은 첨부파일 Header Column 에만 설정, 이미지 원본 크기는 16 x 16, 이미지는 텍스트 오른쪽에 표시\n[확인] 이미지 스타일 확인 버튼 -> Header Column 이미지의 style / class 속성, 크기, 텍스트와의 간격, 텍스트 대비 세로 위치"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // 바인딩 dataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="docNo" name="docNo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="file" name="file" dataType="text"></w2:column>';
    strDlt += '<w2:column id="writer" name="writer" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "docNo" : "D-2026-001", "file" : "견적서.pdf", "writer" : "김민수" },
        { "docNo" : "D-2026-002", "file" : "계약서.docx", "writer" : "이영희" },
        { "docNo" : "D-2026-003", "file" : "회의록.hwp", "writer" : "박지훈" }
    ], false);

    // 검증 대상 Header Column 속성
    let attrHeader = ' inputType="' + cInputType + '" viewType="' + cViewType + '" imageSrc="/cm/images/base/ico_file.svg"';
    if (cImageStyle !== '') {
        attrHeader += ' imageStyle="' + cImageStyle + '"';
    }
    if (cImageWidthHeight !== '') {
        attrHeader += ' imageWidth="' + cImageWidthHeight + '" imageHeight="' + cImageWidthHeight + '"';
    }

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:500px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="문서번호"></w2:column>';
    strTarget += '<w2:column width="220" style="" id="column2" value="첨부파일"' + attrHeader + '></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column3" value="등록자"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="docNo" value=""></w2:column>';
    strTarget += '<w2:column width="220" style="" inputType="text" id="file" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="writer" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 영역 안 텍스트(이미지 제외)의 화면 영역 (여러 텍스트 노드면 합친 영역)
scwin.getTextRect = function (area) {
    let walker = document.createTreeWalker(area, NodeFilter.SHOW_TEXT);
    let rect = null;
    while (walker.nextNode()) {
        let node = walker.currentNode;
        if (node.nodeValue.trim() === "") {
            continue;
        }
        let range = document.createRange();
        range.selectNodeContents(node);
        let r = range.getBoundingClientRect();
        if (r.width === 0) {
            continue;
        }
        if (!rect) {
            rect = { left : r.left, right : r.right, top : r.top, bottom : r.bottom };
        } else {
            rect.left = Math.min(rect.left, r.left);
            rect.right = Math.max(rect.right, r.right);
            rect.top = Math.min(rect.top, r.top);
            rect.bottom = Math.max(rect.bottom, r.bottom);
        }
    }
    return rect;
}



// validation 1 ~ 4 판정 출력 : Header Column 이미지의 style / class 속성, 표시 크기, 텍스트와의 간격, 텍스트 대비 세로 위치
//  - 세로 위치 = 이미지 세로 중심 - 텍스트 세로 중심 (0 에 가까울수록 가운데 정렬)
scwin.btn_checkImageStyle_onclick = function () {
    let th = document.querySelector("[id='" + target1.id + "_column2']");
    let img = th ? th.querySelector("img") : null;
    if (!img) {
        wf_body_bottom.getObj("scwin").setReturnValue("Header Column : 이미지 없음");
        return;
    }
    let styleAttr = img.getAttribute("style");
    let classAttr = img.getAttribute("class");
    let imgRect = img.getBoundingClientRect();
    let textRect = scwin.getTextRect(th);
    let result = "Header Column 이미지 : style 속성 = " + (styleAttr === null ? "없음" : styleAttr)
        + " / class 속성 = " + (classAttr === null ? "없음" : classAttr)
        + " / 크기 " + Math.round(imgRect.width) + " x " + Math.round(imgRect.height) + "px";
    if (textRect) {
        let gap = Math.round(imgRect.left - textRect.right);
        let offsetY = Math.round((imgRect.top + imgRect.height / 2) - (textRect.top + textRect.bottom) / 2);
        result += " / 텍스트와의 간격 " + gap + "px / 텍스트 대비 세로 위치 " + offsetY + "px";
    }
    wf_body_bottom.getObj("scwin").setReturnValue(result);
}
